function [same, report, n_diff] = compare_outputs(file_old, file_new, tolerance, max_report)

% function to compare all the variables saved in two .mat files (generated by the old and the new version of the code)
% (revised October 2026)

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   INPUTS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% file_old / file_new:  .mat files to compare
% tolerance:            relative tolerance for numeric values: |a-b| <= tolerance*max(|a|,|b|,1) (default: 0, exact comparison)
% max_report:           maximum number of differences listed in the report (default: 200)

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   OUTPUT   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% same:                 true if all variables are equal (numeric values within the tolerance; NaN == NaN)
% report:               string array, one line per difference (e.g., "spikeTimestamp(12).timeStamp: 3 of 1520 values differ (max abs diff 0.05)")
% n_diff:               total number of differences found (it can be larger than the number of lines in the report)

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

if nargin < 3, tolerance = 0; end
if nargin < 4, max_report = 200; end

S_old = load(file_old);                                                     % all variables saved by the old version
S_new = load(file_new);                                                     % all variables saved by the new version

state.report = strings(0,1);    state.n_diff = 0;   state.tol = tolerance;  state.max_report = max_report;
state = compare_value(S_old, S_new, '', state);                             % recursive comparison, starting from the list of variables

report = state.report;
n_diff = state.n_diff;
same = n_diff == 0;
if n_diff > numel(report)
    report(end+1) = sprintf('... and %g more differences', n_diff - numel(report));
end

end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function state = compare_value(a, b, name, state)

% recursive comparison of two values (structures, cells, tables, numeric arrays, strings, ...)

if ~strcmp(class(a), class(b))                                              % different type of variable
    state = add_diff(state, sprintf('%s: class %s (old) vs %s (new)', name, class(a), class(b)));
    return
end
if istable(a)                                                               % tables: compare the variable names and the content, column by column
    if ~isequal(a.Properties.VariableNames, b.Properties.VariableNames)
        state = add_diff(state, sprintf('%s: different table columns', name));
        return
    end
    a = table2struct(a, 'ToScalar', true);   b = table2struct(b, 'ToScalar', true);
end
if ~isequal(size(a), size(b))                                               % different dimensions
    state = add_diff(state, sprintf('%s: size [%s] (old) vs [%s] (new)', name, num2str(size(a)), num2str(size(b))));
    return
end

if isstruct(a)                                                              % structures: compare field by field, element by element
    fa = fieldnames(a);     fb = fieldnames(b);
    missing = setdiff(fa, fb);  extra = setdiff(fb, fa);
    for k=1:numel(missing)
        state = add_diff(state, sprintf('%s.%s: missing in the new version', name, missing{k}));
    end
    for k=1:numel(extra)
        state = add_diff(state, sprintf('%s.%s: new field (not in the old version)', name, extra{k}));
    end
    common = intersect(fa, fb, 'stable');
    if isequaln(a, b)                                                       % quick exit (most of the time)
        return
    end
    for i=1:numel(a)
        if numel(a) > 1
            elem = sprintf('%s(%g)', name, i);
        else
            elem = name;
        end
        for k=1:numel(common)
            if isempty(elem)
                field_name = common{k};                                     % top level: the field is a saved variable
            else
                field_name = sprintf('%s.%s', elem, common{k});
            end
            state = compare_value(a(i).(common{k}), b(i).(common{k}), field_name, state);
        end
    end

elseif iscell(a)                                                            % cell arrays: compare element by element
    if isequaln(a, b)
        return
    end
    for i=1:numel(a)
        state = compare_value(a{i}, b{i}, sprintf('%s{%g}', name, i), state);
    end

elseif isnumeric(a) || islogical(a)                                         % numeric arrays: exact comparison, or within the tolerance
    if isequaln(a, b)
        return
    end
    a = double(a(:));   b = double(b(:));
    nan_mismatch = isnan(a) ~= isnan(b);                                    % NaN in only one of the versions
    delta = abs(a - b);     delta(isnan(a) & isnan(b)) = 0;
    scale = max(max(abs(a), abs(b)), 1);
    bad = nan_mismatch | delta > state.tol*scale;
    if any(bad)
        state = add_diff(state, sprintf('%s: %g of %g values differ (max abs diff %.6g)', name, sum(bad), numel(a), max(delta(bad & ~nan_mismatch), [], 'omitnan')));
    end

else                                                                        % strings, chars, function handles, ...
    if ~isequaln(a, b)
        state = add_diff(state, sprintf('%s: different values', name));
    end
end

end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function state = add_diff(state, line)

% function to register one difference (only the first "max_report" are listed)

state.n_diff = state.n_diff + 1;
if numel(state.report) < state.max_report
    state.report(end+1,1) = string(line);
end

end
